const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  const getInfo = (eeObj) =>
    new Promise((resolve, reject) => {
      eeObj.getInfo((res, err) => (err ? reject(err) : resolve(res)));
    });

  // 1. Geometry & Time Definitions (Leipzig Neuseenland bounding box)
  const roi = ee.Geometry.Polygon(
    [[[12.2, 51.15], [12.6, 51.15], [12.6, 51.35], [12.2, 51.35], [12.2, 51.15]]],
    null,
    false
  );
  const periodA = { label: '1987-04', start: '1987-04-01', end: '1987-05-01' };
  const periodB = { label: '2020-04', start: '2020-04-01', end: '2020-05-01' };
  const reduceScale = 1000; // per guidance to avoid timeout
  const maxPix = 1e9;
  const mndwiThresh = 0.0;

  // 2. Sensor setup
  function landsatCol(sensor, start, end) {
    const idMap = {
      LT05: 'LANDSAT/LT05/C02/T1_L2',
      LT04: 'LANDSAT/LT04/C02/T1_L2',
      LC08: 'LANDSAT/LC08/C02/T1_L2'
    };
    return ee.ImageCollection(idMap[sensor])
      .filterBounds(roi)
      .filterDate(start, end);
  }
  function maskLandsatL2(img) {
    const qa = img.select('QA_PIXEL');
    const clear = qa.bitwiseAnd(1 << 6).neq(0); // clear bit
    return img.updateMask(clear);
  }
  function scaleL2(img) {
    const scale = 0.0000275;
    const offset = -0.2;
    const srBands = img.select(img.bandNames().filter(ee.Filter.stringContains('item', 'SR_B')));
    const scaled = srBands.multiply(scale).add(offset);
    return img.addBands(scaled, null, true);
  }
  function landsatMNDWI(img, sensor) {
    // L5/L4: green=SR_B2, swir1=SR_B5; L8: green=SR_B3, swir1=SR_B6
    const green = sensor === 'LC08' ? 'SR_B3' : 'SR_B2';
    const swir1 = sensor === 'LC08' ? 'SR_B6' : 'SR_B5';
    const mndwi = img.expression(
      '(g - s) / (g + s)',
      { g: img.select(green), s: img.select(swir1) }
    ).rename('MNDWI');
    return img.addBands(mndwi);
  }
  function s2Collection(start, end) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(roi)
      .filterDate(start, end)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
  }
  function maskS2(img) {
    const scl = img.select('SCL');
    // Keep: 2 (Dark Features), 4 (Vegetation), 5 (Bare soil), 6 (Water), 7 (Unclassified)
    const mask = scl.eq(2).or(scl.eq(4)).or(scl.eq(5)).or(scl.eq(6)).or(scl.eq(7));
    return img.updateMask(mask);
  }
  function s2MNDWI(img) {
    // Sentinel-2: green=B3, swir1=B11
    const mndwi = img.expression(
      '(g - s) / (g + s)',
      { g: img.select('B3'), s: img.select('B11') }
    ).rename('MNDWI');
    return img.addBands(mndwi);
  }

  async function buildComposite(period, sensorsPriority) {
    let chosen = null;
    for (const s of sensorsPriority) {
      let col;
      if (s === 'S2') {
        col = s2Collection(period.start, period.end);
      } else {
        col = landsatCol(s, period.start, period.end);
      }
      const size = await getInfo(col.size());
      console.log(`${period.label} ${s} images: ${size}`);
      if (size > 0 && chosen === null) {
        let processed;
        if (s === 'S2') {
          processed = col.map(maskS2).map(s2MNDWI).select('MNDWI');
        } else {
          processed = col.map(maskLandsatL2).map(scaleL2).map(img => landsatMNDWI(img, s)).select('MNDWI');
        }
        const composite = processed.median().clip(roi);
        chosen = { image: composite, sensor: s };
      }
    }
    return chosen;
  }

  async function computeStats(label, img) {
    // Counts of total and valid pixels at reduceScale
    const totalPx = await getInfo(
      ee.Image.constant(1)
        .rename('const')
        .reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: roi,
          scale: reduceScale,
          maxPixels: maxPix
        }).get('const')
    );
    const validPx = await getInfo(
      img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: reduceScale,
        maxPixels: maxPix
      }).get('MNDWI')
    );
    const validPct = totalPx && validPx ? (100 * validPx / totalPx) : null;

    // Water area (km2)
    const waterMask = img.gt(mndwiThresh);
    const waterAreaKm2 = await getInfo(
      ee.Image.pixelArea()
        .updateMask(waterMask)
        .reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: roi,
          scale: reduceScale,
          maxPixels: maxPix
        }).get('area')
    );
    const waterKm2 = waterAreaKm2 ? (waterAreaKm2 / 1e6) : null;

    console.log(`${label} ValidPx: ${validPx}/${totalPx} (${validPct !== null ? validPct.toFixed(1) : 'NA'}%), Water_km2: ${waterKm2 !== null ? waterKm2.toFixed(2) : 'NA'}`);
    return { totalPx, validPx, validPct, waterKm2 };
  }

  try {
    // ROI area for validation
    const roiAreaKm2 = await getInfo(
      ee.Image.pixelArea().reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: roi,
        scale: reduceScale,
        maxPixels: maxPix
      }).get('area')
    ).then(v => v / 1e6);
    console.log(`ROI_km2: ${roiAreaKm2.toFixed(1)}`);

    // 3. Data Acquisition & Check (+ fallbacks)
    const comp1987 = await buildComposite(periodA, ['LT05', 'LT04', 'LC08', 'S2']);
    const comp2020 = await buildComposite(periodB, ['LC08', 'S2']);

    if (!comp1987 || !comp2020) {
      console.log('One or both periods have empty collections after fallbacks.');
      console.log('C1');
      return;
    }

    // 4. Processing and pixel validity checks
    const statsA = await computeStats(periodA.label, comp1987.image);
    const statsB = await computeStats(periodB.label, comp2020.image);

    if ((statsA.validPx || 0) === 0 || (statsB.validPx || 0) === 0) {
      console.log('No valid pixels after masking for one or both periods.');
      console.log('C2');
      return;
    }

    // 5. Validation of results
    const invalidA = statsA.waterKm2 === null || isNaN(statsA.waterKm2) || statsA.waterKm2 < 0 || statsA.waterKm2 > roiAreaKm2 * 1.05;
    const invalidB = statsB.waterKm2 === null || isNaN(statsB.waterKm2) || statsB.waterKm2 < 0 || statsB.waterKm2 > roiAreaKm2 * 1.05;
    if (invalidA || invalidB) {
      console.log('Computed water area is invalid (null/NaN/out of range).');
      console.log('C3');
      return;
    }

    // 6. Comparison and final result
    const diff = statsB.waterKm2 - statsA.waterKm2;
    console.log(`WaterDiff_km2 (2020-1987): ${diff.toFixed(2)}`);
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
